#include <cstdio>
#include <cstring>
#include <algorithm>
#define FORI(i,a,b) for(int i=a;i<=b;i++)
#define FORD(i,a,b) for(int i=a;i>=b;i--)
using namespace std;

typedef long long ll;

const int MAX_SIZE=262144;

int L,n,k,Mo,len,bit[20],fac[MAX_SIZE],inv[MAX_SIZE],cnt[MAX_SIZE],g[20][MAX_SIZE],f[20][MAX_SIZE],h[20],p[20];

int qpower(int base,int exp) {
	int res=1;
	while (exp>0) {
		if (exp&1) res=(ll)res*base%Mo;
		base=(ll)base*base%Mo;
		exp>>=1;
	}
	return res;
}

void add_mod(int &x,int y) {x=x+y>=Mo?x+y-Mo:x+y;}
void sub_mod(int &x,int y) {x=x-y<0?x-y+Mo:x-y;}
void transform_FWT(int *a,int len) {
	for(int i=1;i<len;i<<=1) {
		for(int j=0;j<len;j+=i<<1) {
			for(int k=0;k<i;k++) {
				add_mod(a[j+k+i],a[j+k]);
			}
		}
	}
}
void inverse_FWT(int *a,int len) {
	for(int i=1;i<len;i<<=1) {
		for(int j=0;j<len;j+=i<<1) {
			for(int k=0;k<i;k++) {
				sub_mod(a[j+k+i],a[j+k]);
			}
		}
	}
}

void compute_logarithm(int *a,int *b,int n) {
	b[0]=0;
	FORI(i,1,n) {
		b[i]=(ll)a[i]*i%Mo;
		FORI(j,1,i-1) {
			b[i]+=(Mo-(ll)b[j]*a[i-j]%Mo*j)%Mo;
		}
		b[i]=(ll)b[i]*qpower(i,Mo-2)%Mo;
	}
}

void compute_exponential(int *a,int *b,int n) {
	b[0]=1;
	FORI(i,1,n) {
		b[i]=0;
		FORI(j,1,i) {
			b[i]+=(ll)a[j]*b[i-j]%Mo*j%Mo;
		}
		b[i]=(ll)b[i]*qpower(i,Mo-2)%Mo;
	}
}

int main() {
	scanf("%d%d%d",&L,&k,&Mo);
	int total=1;
	for(int i=0;i<L;i++) total=(ll)total*k%Mo;
	if (L&1) {
		printf("%d\n",total);
		return 0;
	}
	fac[0]=1; FORI(i,1,L) fac[i]=(ll)fac[i-1]*i%Mo;
	inv[L]=qpower(fac[L],Mo-2); FORD(i,L-1,0) inv[i]=(ll)inv[i+1]*(i+1)%Mo;
	FORI(s,1,L) cnt[s]=cnt[s^(s&-s)]+1;
	FOR(i,0,18) if (L>>i&1) bit[++n]=1<<i;
	len=1<<n;
	FORI(i,0,len-1) {
		int s=0;
		FORI(j,1,n) if (i>>(j-1)&1) s+=bit[j];
		g[cnt[i]][i]=inv[s];
	}
	transform_FWT(g[0],len);
	transform_FWT(g[1],len);
	transform_FWT(g[2],len);
	FORI(s,0,len-1) {
		FOR(i,0,n) h[i]=g[i][s];
		get_ln(h,p,n);
		FOR(i,0,n) p[i]=(ll)p[i]*k%Mo;
		get_exp(p,h,n);
		FOR(i,0,n) f[i][s]=h[i];
	}
	inverse_FWT(f[n],len);
	int answer=(ll)f[n][len-1]*fac[L]%Mo;
	answer=(total-answer+Mo)%Mo;
	printf("%d\n",answer);
	return 0;
}
